export function routeMessage(message: string, messageCountInChat: number): RouteResult {
  const lower = message.toLowerCase().trim()
  const length = message.length

  // CRISIS: always full everything — checked FIRST so a first-message
  // disclosure is not mislabeled as 'deep'
  if (CRISIS_WORDS.some(w => lower.includes(w))) {
    return { tier: 'crisis', memoryCount: MAX_CONTEXT_MEMORIES, historyLimit: 50, includeStats: true, includeFullPrompt: true, includeProfile: true }
  }

  // Always full context for first message in a chat session
  if (messageCountInChat === 0) {
    return { tier: 'deep', memoryCount: MAX_CONTEXT_MEMORIES, historyLimit: 50, includeStats: true, includeFullPrompt: true, includeProfile: true }
  }
  // ... rest unchanged (DEEP, CASUAL, NORMAL)
}

This is safe and non-breaking: it only flips the tier label from 'deep' to 'crisis' for the narrow first-message-with-crisis-word case; all RouteResult fields are otherwise identical, and the charBudget branch resolves the same. NOTE: this fix is necessary but NOT sufficient — it only matters once crisis-specific behavior actually exists. It should be landed together with ai-aiya-1 (adding crisis instructions to the system prompt and/or a tier-keyed behavior), otherwise the reorder is a no-op at runtime today.

